(function () { const header = document.getElementById('header'); if (!header) return; const HERO_THRESHOLD = 100; function onScroll() { if (window.scrollY > HERO_THRESHOLD) { header.classList.remove('is-transparent'); header.classList.add('is-sticky'); } else { header.classList.remove('is-sticky'); header.classList.add('is-transparent'); } } window.addEventListener('scroll', onScroll, { passive: true }); onScroll(); })();